  function cqPersist(){try{localStorage.setItem(cqStorage,JSON.stringify(cqState));return true}catch{toast('本机保存失败，请导出报价备份');return false}}
  function cqRows(){return $$('#quoteLines tr')}
  function cqCapture(){if(module==='custom'&&$('#cqRoomNav')){cqState.draft=quoteDraftFromPage();quoteDraftId=cqState.draft.id;const saved=cqPersist(),s=$('#cqDraftStatus');if(s)s.textContent=saved?'草稿已自动保存 · 本机':'本次编辑未保存，请导出备份后再离开'}}
  function cqNav(){return `<nav class="workshop-module-nav">${[['home','工作台'],['list','定制报价'],['hardware','配套与升级'],['materials','板材与门板'],['additions','增减项'],['templates','报价模板'],['settings','报价规则']].map(([id,label])=>`<button data-action="cq-section" data-section="${id}" class="${cqSection===id||(cqSection==='builder'&&id==='list')?'active':''}">${label}</button>`).join('')}</nav>`}
  function cqHead(title,desc,buttons=''){return head('全屋定制 / 报价系统',title,desc,buttons)+cqNav()}
  function cqHome(){const quotes=savedQuotes.filter(q=>q.type==='全屋定制');return cqHead('定制报价系统','先建立客户档案，再从本户详情发起报价。报价单按全屋柜体清单统一录入。',`<button class="btn primary" data-action="new-customer-for-quote">＋ 新建客户</button>`)+`<div class="cq-home-intro"><div><small>CUSTOM QUOTATION</small><h2>一户一份报价，规格说清楚</h2><p>基础柜体报价 + 特殊项目增项 + 五金升级补差，报价书说明包含范围。</p></div><div><strong>${quotes.length}</strong><span>已保存报价</span></div></div><div class="quote-module-grid">${[['list','定制报价','按客户与空间管理报价，尺寸算量、报价版本、整户汇总。','▤'],['hardware','配套与升级','基础铰链、滑道已含；灯带、玻璃门与特殊工艺另列，进口五金升级补差。','⚙'],['materials','板材与门板','品牌、基材、厚度、花色、饰面、环保等级逐项确认。','▦'],['additions','增减项','改颜色、换五金、加柜体，记录变更金额及客户确认。','±'],['templates','报价模板','零售客户和装饰公司两种报价书，保留交付与签字栏。','▧'],['settings','报价规则','投影、延米、按数量与展开面积，设置默认交付约定。','⌘']].map(([id,title,desc,icon])=>`<button class="quote-module-card" data-action="cq-section" data-section="${id}"><span class="quote-module-glyph">${icon}</span><strong>${title}</strong><p>${desc}</p><span class="quote-module-link">进入模块 →</span></button>`).join('')}</div>${cqState.draft?.rows?.length?`<div class="cq-resume"><span>上次编辑：${esc(cqState.draft.customer)} · ${cqState.draft.rows.length} 项 · ${money(cqState.draft.amount)}</span><button class="btn" data-action="cq-resume">继续编辑草稿</button></div>`:''}`}
  function cqList(){const rows=savedQuotes.filter(q=>q.type==='全屋定制');return cqHead('定制报价','按客户保留报价版本；每版分别记录材料、五金和交付范围。',`<button class="btn primary" data-action="new-customer-for-quote">＋ 新建客户并报价</button>`)+`<div class="quote-list-toolbar"><span>${rows.length} 份定制报价</span><label class="search">⌕<input id="quoteListSearch" placeholder="搜索客户、小区或报价单号"></label>${cqState.draft?'<button class="btn" data-action="cq-resume">继续草稿</button>':''}</div><div class="quote-saved-grid">${rows.map(q=>`<article class="quote-saved-card"><div class="quote-saved-top"><span>${esc(q.customerType||'零售客户')}</span><small>${esc(q.id)}</small></div><h3>${esc(q.customer)}</h3><p>${esc(q.address||'地址待补充')}</p><div class="quote-saved-bottom"><span>${q.rows.length} 项 · ${esc(q.date)}</span><b>${money(q.amount)}</b></div><div class="workshop-saved-actions"><button class="btn small" data-action="cq-open" data-id="${esc(q.id)}">打开编辑</button><button class="btn small" data-action="cq-copy" data-id="${esc(q.id)}">复制新版本</button><button class="btn small" data-action="cq-preview-saved" data-id="${esc(q.id)}">客户报价书</button><button class="btn small" data-action="fo-from-quote" data-id="${esc(q.id)}">转工厂接单摘要</button></div></article>`).join('')||'<section class="quote-list-empty"><h3>建立第一份定制报价</h3><p>选客户 → 建空间 → 选项目与材料 → 核价 → 输出报价书</p><button class="btn primary" data-action="new-customer-for-quote">＋ 新建客户并报价</button></section>'}</div>`}
  function cqRoomNav(){return cqRooms.map(r=>`<button class="workshop-room ${r===cqRoom?'active':''}" data-action="cq-room" data-room="${esc(r)}"><span>${esc(r)}</span><small data-cq-room-total="${esc(r)}">¥0.00</small><i>›</i></button>`).join('')}
  function cqBuilder(){const q=cqState.draft||{},customers=sampleCustomers.filter(c=>uxCustomerDomain(c)==='custom'&&(role!=='sales'||c.owner==='设计师A'));return cqHead('定制报价工作台','先报基础柜体（含常规铰链、滑道），再录入灯带、玻璃门、特殊工艺与升级补差。',`<button class="btn" data-action="cq-section" data-section="list">返回报价列表</button><button class="btn" data-action="cq-export">导出备份</button><button class="btn" data-action="quote-print">客户报价书</button><button class="btn primary" data-action="save-quote">保存本版报价</button>`)+`
  <details class="workshop-client" open><summary><b>客户与报价信息</b><span>${esc(q.customerType||'零售客户')} · ${esc(q.id||'新报价')}</span></summary><div class="workshop-client-grid"><label>客户 / 小区<select id="quoteCustomer" class="field">${customers.map(c=>`<option value="${esc(c.id||c.name)}" data-owner="${esc(c.owner)}">${esc(c.name)} · ${esc(c.community)}</option>`).join('')}</select></label><label>报价类型<select class="field" id="cqCustomerType"><option>零售客户</option><option>渠道客户</option></select></label><label>项目地址<input class="field" id="quoteAddress" placeholder="楼栋、单元、房号"></label><label>设计师 / 经办人<select class="field" id="quoteOwner">${['设计师A','设计师B','设计师C'].map(n=>`<option>${n}</option>`).join('')}</select></label><label>报价日期<input class="field" type="date" id="quoteDate" value="${new Date().toLocaleDateString('sv-SE')}"></label><label>联系人<input class="field" id="cqContact"></label><label>联系电话<input class="field" id="cqPhone" type="tel"></label><label>装饰公司 / 渠道<input class="field" id="cqChannel" placeholder="渠道订单填写"></label></div><div class="workshop-client-grid cq-client-print-fields"><label>工厂单号<input class="field" id="cqOrderNo" placeholder="转单后填写 / 可暂空"></label><label>测量日期<input class="field" type="date" id="cqMeasureDate"></label><label>交货日期<input class="field" type="date" id="cqDeliveryDate"></label><label>总投影面积 ㎡<input class="field" type="number" min="0" step=".01" id="cqProjectedArea" placeholder="可按柜体行汇总"></label><label>总柜门面积 ㎡<input class="field" type="number" min="0" step=".01" id="cqDoorArea"></label><label class="full">订单备注<input class="field" id="cqCustomerNote" placeholder="客户可见的订单说明"></label></div></details>${cqBasis(q)}
  <div class="workshop-layout cq-layout"><aside class="workshop-space-panel"><div class="workshop-panel-heading"><b>空间列表</b><button class="icon-btn" data-action="cq-add-room" aria-label="添加定制空间">＋</button></div><div id="cqRoomNav">${cqRoomNav()}</div><div class="cq-space-actions"><button class="btn small" data-action="cq-rename-room">编辑空间名称</button></div><div class="cq-rule-note"><b>定制算量</b><p>投影：宽 × 高 × 数量<br>延米：宽 × 数量<br>展开：拆单板件面积手填</p><small>柜体与柜门分项时，确认各自报价范围。</small></div><div class="workshop-house-total"><small>整户客户报价</small><strong id="quoteTotal">¥0.00</strong><span id="quoteSummaryCount">0 项</span></div><button class="btn primary workshop-full" data-action="quote-print">预览客户报价书</button><small id="cqDraftStatus" class="workshop-draft-status">草稿自动保存在本机</small></aside>
  <div class="workshop-main"><section class="workshop-sheet"><div class="workshop-sheet-head"><div><h2 id="cqRoomTitle">${esc(cqRoom)}</h2><span>基础报价与增项 / 升级明细</span></div><div class="workshop-sheet-actions">${role==='owner'?'<button class="btn small" data-action="cq-cost">内部预算</button>':''}<button class="btn small primary" data-action="cq-picker">＋ 添加项目</button></div></div><div class="workshop-category-strip">${cqGroups.map(g=>`<button data-action="cq-picker" data-group="${g}">${g} ＋</button>`).join('')}<span class="spacer"></span><button data-action="quote-bulk-import">粘贴清单</button><button data-action="add-line">手动新增</button></div><div class="quote-lines-scroll"><table class="quote-line-table workshop-line-table cq-line-table ${cqCostVisible?'show-cost':''}"><thead><tr><th>空间 / 分类</th><th>报价项目</th><th>计价方式</th><th>尺寸 mm / 算量</th><th>数量</th><th>计价量</th><th>客户单价 / 补差</th><th>收费方式</th><th>金额</th><th class="workshop-cost-col">预算成本/单位</th><th>规格 / 五金型号</th><th></th></tr></thead><tbody id="quoteLines"></tbody></table><div class="quote-empty" id="quoteEmpty"><b>先把这户要做的东西列出来</b><span>选择柜体或五金，再核对尺寸、规格与客户单价。</span><button class="btn primary" data-action="cq-picker">＋ 添加第一个项目</button></div></div><div class="workshop-sheet-foot"><span id="quoteLineCount">0 个项目</span><span class="spacer"></span><span>当前空间 <b id="cqSpaceTotal">¥0.00</b></span></div></section>
  <section class="workshop-summary"><div class="workshop-panel-heading"><b>整户汇总</b><span>已含项目不重复收费</span></div><div class="workshop-room-summary" id="cqRoomSummary"></div><div class="cq-fees"><label>整单优惠 ¥<input class="field" type="number" min="0" step=".01" id="cqDiscount" value="0"></label><label>额外运输 / 上楼 ¥<input class="field" type="number" min="0" step=".01" id="cqDeliveryFee" value="0"></label><label>额外安装费 ¥<input class="field" type="number" min="0" step=".01" id="cqInstallFee" value="0"></label></div><div class="workshop-grand-total"><span>客户报价总额<small>分项合计 − 优惠 + 单独约定的运输与安装费用</small></span><strong id="cqGrandTotal">¥0.00</strong></div><div id="cqValidation" class="cq-validation"></div><div id="cqLiveStats" class="cq-live-stats"></div>${role==='owner'?'<div class="workshop-internal-summary"><span>已录预算成本 <b id="quoteCostTotal">¥0.00</b></span><span>报价减已录预算 <b id="quoteMarginTotal">¥0.00</b></span><small>预算缺项时不代表实际利润；采购与加工实际成本在工厂订单归集。</small></div>':''}</section>
  <details class="workshop-terms" open><summary>客户确认与交付约定</summary><div class="quote-info-grid"><label>报价有效期<select class="field" id="quoteValidity"><option>7天</option><option>15天</option><option>30天</option></select></label><label>运输 / 安装范围<input class="field" id="quoteDelivery" placeholder="是否包含运输、上楼、安装，现场条件"></label><label>包含范围<textarea class="field" id="quoteRequirements" placeholder="柜体与柜门、常规五金、见光板等是否包含"></textarea></label><label>不含 / 待确认<textarea class="field" id="quoteExclusions" placeholder="特殊五金、基层、水电、拆改等"></textarea></label><label>付款节点<input class="field" id="cqPayments" placeholder="签约__%；下单__%；安装__%；尾款__%"></label><label>渠道结算约定（内部）<input class="field" id="cqChannelTerms" placeholder="返点、结算周期等；不输出到客户报价书"></label></div><div class="cq-documents"><b>本户参考资料</b><p>可保存原始客户报价单、板材单、五金单；此处归档不自动生成采购成本。</p><input class="field" id="cqFiles" type="file" accept="image/*,.pdf,.xlsx,.xls,.csv" multiple><div id="cqDocuments"></div></div></details><details class="cq-live-preview" open><summary>A4客户报价单实时预览</summary><div id="cqLivePreview"></div></details><div class="workshop-bottom-actions"><button class="btn" data-action="quote-print">预览 / 打印客户报价书</button><button class="btn primary" data-action="save-quote">保存本版报价</button></div></div></div>`}
  function cqLine(r={}){const mode=r.mode||'按数量',m=r.material||{},unit=r.unit||'项';return `<tr data-cq-row data-last-charge="${r.included?'included':r.charge||'extra'}" data-upgrade-price="${Number(r.upgradePrice??(r.charge==='upgrade'?r.price:0)??0)}" data-standalone-price="${Number(r.standalonePrice??(r.charge==='upgrade'?0:r.price)??0)}" data-material="${esc(JSON.stringify(m))}" data-source="${esc(r.source||'')}" data-reference="${esc(r.purchaseReference??'')}"><td><input type="hidden" data-room value="${esc(r.room||cqRoom)}"><small>${esc(r.room||cqRoom)}</small><select data-category aria-label="项目分类">${[...new Set([r.category||'未分类',...cqGroups])].map(g=>`<option ${g===(r.category||'未分类')?'selected':''}>${esc(g)}</option>`).join('')}</select></td><td><input data-item value="${esc(r.name||'')}" placeholder="项目名称"><button class="cq-link" data-action="cq-spec">编辑材料 / 型号</button></td><td><select data-unit aria-label="定制计价方式">${['投影面积','展开面积','延米','按数量','按件','按项'].map(v=>`<option ${mode===v?'selected':''}>${v}</option>`).join('')}</select><small class="quote-unit-hint" data-unit-label="${esc(unit)}">${esc(unit)}</small></td><td><div class="cq-size-fields">${[['width','宽',r.width],['height','高',r.height],['depth','深',r.depth]].map(([k,n,v])=>`<label>${n}<input data-${k} type="number" min="0" step="1" value="${Number(v||0)}" aria-label="${n} mm"></label>`).join('')}</div><label class="cq-expanded-field">展开面积 ㎡<input data-expanded type="number" min="0" step=".001" value="${Number(r.expandedArea||0)}" aria-label="单件展开面积"></label></td><td><input data-qty type="number" min="0" step=".001" value="${Number(r.qty??1)}" aria-label="定制数量"></td><td data-measure-qty class="quote-calculated-qty">0</td><td><input data-price type="number" min="0" step=".01" value="${Number(r.price||0)}" aria-label="客户单价" ${r.included?'disabled':''}></td><td><select data-included aria-label="收费方式"><option value="extra" ${!r.included&&r.charge!=='upgrade'?'selected':''}>单独收费</option><option value="included" ${r.included?'selected':''}>基础价已含</option><option value="upgrade" ${r.charge==='upgrade'?'selected':''}>升级补差</option></select><small class="cq-charge-note">按确认补差单价收费</small><input data-included-in value="${esc(r.includedIn||'')}" placeholder="已含在哪个柜体" aria-label="包含项目"></td><td data-amount class="money">¥0.00</td><td class="workshop-cost-col"><input data-cost type="number" min="0" step=".01" value="${Number(r.cost||0)}" aria-label="预算成本单价">${role==='owner'&&r.purchaseReference!==undefined?`<small>原单采购参考 ${money(r.purchaseReference)}/${esc(unit)}<br>须核定用量与加工成本</small>`:''}</td><td><textarea data-spec rows="3" placeholder="品牌 / 基材 / 厚度 / 花色 / 环保等级 / 封边 / 型号">${esc(r.spec||'')}</textarea><textarea data-remark rows="2" placeholder="备注 / 安装要求">${esc(r.remark||'')}</textarea></td><td><button class="icon-btn" data-action="remove-line" aria-label="删除定制项目">×</button></td></tr>`}
  function cqLoad(q){cqState.draft=q?JSON.parse(JSON.stringify(q)):null;cqRooms=q?.rooms?.length?[...q.rooms]:[...new Set(q?.rows?.map(r=>r.room)||[])];if(!cqRooms.length)cqRooms=['入户','客厅','餐厅','主卧','次卧','厨房','阳台','书房','卫生间'];cqRoom=q?.activeRoom&&cqRooms.includes(q.activeRoom)?q.activeRoom:cqRooms[0];quoteSpace=cqRoom;quoteDraftId=q?.id||'';quotePricingMode='combined'}
  function cqRestore(){const q=cqState.draft;quoteDraftId=q?.id||'';quotePricingMode='combined';if(!q){recalc();return}const fields={quoteCustomer:'customerId',quoteOwner:'owner',quoteAddress:'address',quoteDate:'date',quoteValidity:'validity',quoteDelivery:'delivery',quoteRequirements:'requirements',quoteExclusions:'exclusions',cqCustomerType:'customerType',cqContact:'contact',cqPhone:'phone',cqChannel:'channel',cqPayments:'payments',cqChannelTerms:'channelTerms',cqDiscount:'discount',cqDeliveryFee:'deliveryFee',cqInstallFee:'installFee',cqProjectedPrice:'projectedPrice',cqLinearPrice:'linearPrice',cqOrderNo:'factoryOrderNo',cqMeasureDate:'measurementDate',cqDeliveryDate:'deliveryDate',cqProjectedArea:'clientProjectedArea',cqDoorArea:'clientDoorArea',cqCustomerNote:'orderNote'};Object.entries(fields).forEach(([id,k])=>{if($('#'+id)&&q[k]!==undefined)$('#'+id).value=q[k]});$('#quoteLines').innerHTML=(q.rows||[]).map(cqLine).join('');cqRenderFiles(q.documents||[]);recalc()}
  function cqRenderFiles(docs){if(!$('#cqDocuments'))return;$('#cqDocuments').innerHTML=docs.map(x=>`<button class="btn small" data-action="cq-document" data-id="${esc(x.id)}">▧ ${esc(x.name)}</button>`).join('')}
  function cqCatalogCards(items,kind,picking=false){return `<div class="cq-catalog-grid">${items.map((x,i)=>`<article class="cq-catalog-card"><small>${esc(x.source||'用户报价模板')}</small><h3>${esc(kind==='material'?x.brand+' · '+(x.substrate||'基材待确认'):x.name)}</h3><p>${esc(kind==='material'?[x.color,x.thickness,x.finish,x.grade].filter(Boolean).join(' · '):x.notes||x.category)}</p>${kind==='hardware'&&role==='owner'?`<div class="cq-reference">单据采购参考 ${money(x.purchase)}/${esc(x.unit)}<small>历史供货价；客户售价另行核定</small></div>`:''}<button class="btn small" data-action="${kind==='material'?'cq-apply-material':'cq-pick'}" data-kind="${kind}" data-i="${i}">${kind==='material'?'选择此规格':'＋ 加入当前空间'}</button></article>`).join('')}</div>`}
  function cqCatalogPage(kind){return cqHead(kind==='hardware'?'配套与升级参考库':'板材与门板规格库',kind==='hardware'?'供货单用于参考品牌型号。基础件默认已含；升级件设置补差，灯光等另列增项。':'根据你的供货单整理，空白项留待补录；四九尺等原始规格不擅自换算。',`<button class="btn" data-action="cq-resume">返回报价编辑</button>`)+`<div class="cq-catalog-toolbar"><label class="search">⌕<input id="cqCatalogSearch" data-kind="${kind}" placeholder="搜索品牌、型号、颜色或基材"></label><span>${kind==='hardware'?cqHardware.length:cqMaterials.length} 项参考</span></div><div id="cqCatalogContent">${cqCatalogCards(kind==='hardware'?cqHardware:cqMaterials,kind)}</div>`}
  function cqPicker(group){cqGroup=group||cqGroups[0];openModal(`添加定制项目 · ${cqRoom}`,`<div class="modal-body"><label class="search">⌕<input id="cqPickerSearch" placeholder="搜索柜体、项目或五金型号"></label><div class="workshop-category-strip">${[...cqGroups,'供货单五金'].map(g=>`<button data-action="cq-picker-group" data-group="${g}" class="${g===cqGroup?'active':''}">${g}</button>`).join('')}</div><div id="cqPickerContent">${cqPickerContent()}</div></div><div class="modal-foot"><button class="btn primary" data-action="close-modal">完成添加</button></div>`)}
  function cqPickerContent(search=''){const hardware=cqGroup==='供货单五金',all=hardware?cqHardware:customProducts,items=all.map((p,i)=>({p,i})).filter(({p})=>(hardware||p.category===cqGroup)&&[p.name,p.notes,p.category].join(' ').toLowerCase().includes(search.toLowerCase()));return items.map(({p,i})=>`<button class="quote-pick-row" data-action="cq-pick" data-kind="${hardware?'hardware':'product'}" data-i="${i}"><span class="quote-pick-plus">＋</span><span class="quote-pick-main"><b>${esc(p.name)}</b><small>${esc(p.notes||'')} · ${esc(p.mode)} / ${esc(p.unit)}</small></span><span class="quote-pick-price">客户价待录<small>${hardware?'源自五金单':'客户报价模板项目'}</small></span></button>`).join('')||'<p class="empty">没有匹配项目，可使用“手动新增”。</p>'}
  function cqEnsureBuilder(){if(cqSection!=='builder'||!$('#cqRoomNav')){cqLoad(cqState.draft);cqSection='builder';page='quotes';render()}}
